import contextlib

@contextlib.contextmanager
def tag(name):
    print(f'<{name}>')
    try:
        yield
    finally:
        print(f'</{name}>')

def main():
    with tag('a'):
        with tag('b'):
            print('body')
            raise ValueError('boom')

try:
    main()
except ValueError:
    print('caught')
